CREATE TABLE dormitories (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), name text NOT NULL, gender text NOT NULL, capacity int NOT NULL CHECK (capacity > 0));
CREATE TABLE bed_allocations (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), dormitory_id text NOT NULL REFERENCES dormitories(id), student_id text NOT NULL REFERENCES students(id), allocated_at timestamptz NOT NULL DEFAULT now(), released_at timestamptz);
CREATE UNIQUE INDEX active_student_bed_idx ON bed_allocations(school_id, student_id) WHERE released_at IS NULL;
CREATE TABLE exeat_passes (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), student_id text NOT NULL REFERENCES students(id), approved_by text NOT NULL REFERENCES users(id), destination text NOT NULL, reason text NOT NULL, departure timestamptz NOT NULL, expected_return timestamptz NOT NULL, returned_at timestamptz);
CREATE TABLE sickbay_visits (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), student_id text NOT NULL REFERENCES students(id), nurse_id text NOT NULL REFERENCES users(id), symptoms text NOT NULL, treatment text NOT NULL, referral text, visited_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE discipline_incidents (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), student_id text NOT NULL REFERENCES students(id), reported_by text NOT NULL REFERENCES users(id), offence text NOT NULL, severity text NOT NULL, demerit_points int NOT NULL DEFAULT 0, sanction text, hearing_notes text, created_at timestamptz NOT NULL DEFAULT now());
